mapper.sql:
WHERE N.NOTICE_ID = I.NOTICE_ID AND N.DEL_YN = 'N'
AND N.POST_DATE <= #{now}
AND N.CATEGORY_CD = #{categoryCd}
AND (I.LANG_CD = #{langCd} OR (I.LANG_CD = N.BASE_LANG_CD AND NOT EXISTS (SELECT 1 FROM TB_NOTICE_I18N X WHERE X.NOTICE_ID = N.NOTICE_ID AND X.LANG_CD = #{langCd})))
AND (LOWER(I.TITLE) LIKE #{keyword} ESCAPE '\' OR LOWER(I.CONTENT_TEXT) LIKE #{keyword} ESCAPE '\')
